$r = Invoke-RestMethod -Uri "http://localhost:5005/api/auth/login" -Method Post -Body '{"username":"admin","password":"admin"}' -ContentType "application/json"; $t = $r.token; for ($p=1; $p -le 12; $p++) { try { $decl = Invoke-RestMethod -Uri "http://localhost:5005/api/declarations" -Method Post -Headers @{Authorization="Bearer $t"} -Body '{"societeId":"001","exercice":2026,"periode":'$p',"type":0}' -ContentType "application/json"; $id = $decl.id; $c = (Invoke-RestMethod -Uri "http://localhost:5005/api/declarations/$id/lignes?domaine=Decaissement&page=1&size=1" -Method Get -Headers @{Authorization="Bearer $t"}).totalCount; Write-Host "Periode $p: $c lignes"; } catch { Write-Host "Periode $p exists"; } }
